429→func marshalHookInput(input *agent.HookInput) ([]byte, error) {
430→	if input == nil {
431→		return []byte("{}"), nil
432→	}
433→	j := HookInputJSON{
434→		HookType:   string(input.HookType),
435→		SessionID:  input.SessionID,
436→		SessionRef: input.SessionRef,
437→		Timestamp:  input.Timestamp.Format(time.RFC3339),
438→		UserPrompt: input.UserPrompt,
439→		ToolName:   input.ToolName,
440→		ToolUseID:  input.ToolUseID,
441→		ToolInput:  input.ToolInput,
442→		RawData:    input.RawData,
443→	}
444→	data, err := json.Marshal(j)
445→	if err != nil {
446→		return nil, fmt.Errorf("marshal hook input: %w", err)
447→	}
448→	return data, nil
449→}
