451→func marshalAgentSession(s *agent.AgentSession) ([]byte, error) {
452→	j := AgentSessionJSON{
453→		SessionID:     s.SessionID,
454→		AgentName:     string(s.AgentName),
455→		RepoPath:      s.RepoPath,
456→		SessionRef:    s.SessionRef,
457→		StartTime:     s.StartTime.Format(time.RFC3339),
458→		NativeData:    s.NativeData,
459→		ModifiedFiles: s.ModifiedFiles,
460→		NewFiles:      s.NewFiles,
461→		DeletedFiles:  s.DeletedFiles,
462→	}
463→	data, err := json.Marshal(j)
464→	if err != nil {
465→		return nil, fmt.Errorf("marshal agent session: %w", err)
466→	}
467→	return data, nil
468→}
