470→func unmarshalAgentSession(j *AgentSessionJSON) (*agent.AgentSession, error) {
471→	var startTime time.Time
472→	if j.StartTime != "" {
473→		var err error
474→		startTime, err = time.Parse(time.RFC3339, j.StartTime)
475→		if err != nil {
476→			return nil, fmt.Errorf("invalid start_time: %w", err)
477→		}
478→	}
479→	return &agent.AgentSession{
480→		SessionID:     j.SessionID,
481→		AgentName:     types.AgentName(j.AgentName),
482→		RepoPath:      j.RepoPath,
483→		SessionRef:    j.SessionRef,
484→		StartTime:     startTime,
485→		NativeData:    j.NativeData,
486→		ModifiedFiles: j.ModifiedFiles,
487→		NewFiles:      j.NewFiles,
488→		DeletedFiles:  j.DeletedFiles,
489→	}, nil
490→}
