492→func convertTokenUsage(r *TokenUsageResponse) *agent.TokenUsage {
493→	if r == nil {
494→		return nil
495→	}
496→	usage := &agent.TokenUsage{
497→		InputTokens:         r.InputTokens,
498→		CacheCreationTokens: r.CacheCreationTokens,
499→		CacheReadTokens:     r.CacheReadTokens,
500→		OutputTokens:        r.OutputTokens,
501→		APICallCount:        r.APICallCount,
502→	}
503→	if r.SubagentTokens != nil {
504→		usage.SubagentTokens = convertTokenUsage(r.SubagentTokens)
505→	}
506→	return usage
507→}
