  1→// Binary entire-agent-test implements the external agent protocol as a minimal
  2→// reference example. It declares no optional capabilities, making it useful for
  3→// testing the base external-agent integration path.
  4→package main
  5→
  6→import (
  7→	"encoding/json"
  8→	"flag"
  9→	"fmt"
 10→	"io"
 11→	"os"
 12→	"path/filepath"
 13→)
 14→
 15→func main() {
 16→	if len(os.Args) < 2 {
 17→		fatal("usage: entire-agent-test <subcommand> [args...]")
 18→	}
 19→
 20→	var err error
 21→	switch os.Args[1] {
 22→	case "info":
 23→		err = cmdInfo()
 24→	case "detect":
 25→		err = cmdDetect()
 26→	case "get-session-id":
 27→		err = cmdGetSessionID()
 28→	case "get-session-dir":
 29→		err = runGetSessionDir()
 30→	case "resolve-session-file":
 31→		err = runResolveSessionFile()
 32→	case "read-session":
 33→		err = cmdReadSession()
 34→	case "write-session":
 35→		err = cmdWriteSession()
 36→	case "format-resume-command":
 37→		err = runFormatResumeCommand()
 38→	case "read-transcript":
 39→		err = runReadTranscript()
 40→	case "chunk-transcript":
 41→		err = runChunkTranscript()
 42→	case "reassemble-transcript":
 43→		err = cmdReassembleTranscript()
 44→	default:
 45→		fatal("unknown subcommand: " + os.Args[1])
 46→	}
 47→
 48→	if err != nil {
 49→		fatal(err.Error())
 50→	}
 51→}
 52→
 53→// ---------------------------------------------------------------------------
 54→// Subcommand implementations
 55→// ---------------------------------------------------------------------------
 56→
