 58→	return writeJSON(map[string]interface{}{
 59→		"protocol_version": 1,
 60→		"name":             "test-agent",
 61→		"type":             "Test Agent",
 62→		"description":      "Minimal reference implementation of the external agent protocol",
 63→		"is_preview":       true,
