 84→func cmdGetSessionID() error {
 85→	input, err := io.ReadAll(os.Stdin)
 86→	if err != nil {
 87→		return fmt.Errorf("failed to read stdin: %w", err)
 88→	}
 89→	var hookInput struct {
 90→		SessionID string `json:"session_id"`
 91→	}
 92→	if err := json.Unmarshal(input, &hookInput); err != nil {
