161→func runReadTranscript() error {
162→	fs := flag.NewFlagSet("read-transcript", flag.ContinueOnError)
163→	sessionRef := fs.String("session-ref", "", "session reference path")
164→	if err := fs.Parse(os.Args[2:]); err != nil {
165→		return fmt.Errorf("failed to parse flags: %w", err)
166→	}
167→	data, err := os.ReadFile(*sessionRef)
168→	if err != nil {
169→		return fmt.Errorf("failed to read transcript: %w", err)
170→	}
171→	if _, err := os.Stdout.Write(data); err != nil {
172→		return fmt.Errorf("failed to write output: %w", err)
173→	}
174→	return nil
175→}
176→
177→func runChunkTranscript() error {
178→	fs := flag.NewFlagSet("chunk-transcript", flag.ContinueOnError)
179→	maxSize := fs.Int("max-size", 0, "maximum chunk size in bytes")
180→	if err := fs.Parse(os.Args[2:]); err != nil {
181→		return fmt.Errorf("failed to parse flags: %w", err)
182→	}
183→
184→	content, err := io.ReadAll(os.Stdin)
185→	if err != nil {
186→		return fmt.Errorf("failed to read stdin: %w", err)
187→	}
188→
189→	chunkSize := *maxSize
190→	if chunkSize <= 0 {
191→		chunkSize = len(content)
192→	}
193→
194→	// json.Marshal automatically base64-encodes []byte elements.
195→	var chunks [][]byte
196→	for i := 0; i < len(content); i += chunkSize {
197→		end := i + chunkSize
198→		if end > len(content) {
199→			end = len(content)
200→		}
201→		chunks = append(chunks, content[i:end])
202→	}
203→
204→	return writeJSON(map[string]interface{}{
205→		"chunks": chunks,
206→	})
207→}
208→
209→func cmdReassembleTranscript() error {
210→	input, err := io.ReadAll(os.Stdin)
211→	if err != nil {
212→		return fmt.Errorf("failed to read stdin: %w", err)
213→	}
214→
215→	var resp struct {
216→		Chunks [][]byte `json:"chunks"`
217→	}
218→	if err := json.Unmarshal(input, &resp); err != nil {
219→		return fmt.Errorf("failed to unmarshal chunks: %w", err)
220→	}
221→
222→	// json.Unmarshal automatically base64-decodes []byte elements.
223→	for _, chunk := range resp.Chunks {
224→		if _, err := os.Stdout.Write(chunk); err != nil {
225→			return fmt.Errorf("failed to write output: %w", err)
226→		}
227→	}
228→	return nil
229→}
230→
231→// ---------------------------------------------------------------------------
232→// Helpers
233→// ---------------------------------------------------------------------------
234→
235→func writeJSON(v interface{}) error {
236→	data, err := json.Marshal(v)
237→	if err != nil {
238→		return fmt.Errorf("failed to marshal JSON: %w", err)
239→	}
240→	if _, err := os.Stdout.Write(data); err != nil {
241→		return fmt.Errorf("failed to write output: %w", err)
242→	}
243→	return nil
244→}
245→
246→func fatal(msg string) {
247→	fmt.Fprintln(os.Stderr, msg)
248→	os.Exit(1)
249→}
